edits.replace:
  if (/\b(new|junior|incoming|graduate|lateral|locum|contract|temporary|starting)\b[^.]{0,60}\b(hire|starter|nurse|doctor|physician|clinician|resident|staff|employee|trader|analyst|associate|attorney|paralegal|partner|broker|quant|intern|tech|technician|operator|agent|member|user|assistant)\b/.test(q) && /(access|account|provision|set ?up|workstation|onboard|orientation|credential|licen[cs]e|environment|subscription|tools?)/.test(q)) return 'kb:onboarding';
  if (/\b(needs?|requires?)\b[^.]{0,50}\b(access|account|provisioned|set ?up|workstation|credentials?)\b/.test(q) && /\b(new|joining|starting|start(s|ing)? (monday|today|tomorrow|next week)|first day|day one)\b/.test(q)) return 'kb:onboarding';
  return 'default';
}

  if (/(iniciar sesi[oó]n|contrase[nñ]a|no puedo entrar|me connecter|mot de passe|passwort( ist)? (abgelaufen|vergessen)|anmelden nicht)/.test(q)) return 'password';
  if (/\b(cerner|meditech|epic|ehr|emr|citrix|sap|peoplesoft|workday)\b/.test(q) && /(keeps? logging me out|logged out|wont let me in|won'?t let me in|cant access|can'?t access|cannot access|kicked out|credentials? (rejected|not accepted))/.test(q)) return 'password';
  if (/\b(smart ?card|badge|piv|cac) (reader )?(not working|wont read|won'?t read|failing|rejected)\b/.test(q) && /(login|log ?in|sign ?in|logon|authenticat)/.test(q)) return 'password';
  return 'default';
}

  if (/(won\s?t sync|won'?r sync|not sync(ing)?|sharepoint|shared (drive|folder|file|server)|network drive not accessible|file server|document (folder|repository)|folder (missing|gone|not accessible|disappeared)|files? (missing|gone|not accessible)|intranet files?)/.test(q)) return 'kb:onedrive';
  return 'default';
}

  if (/\b(vpm|citrix|rdp|remote desktop|telework|remote session|remote monitoring|offsite|off-site|working from home|work from home)\b/.test(q)) return 'vpn';
  return 'default';
}

  if (/(lagging|lags|hanging|hangs|unresponsive|buffering|pixelated|timing out|times? out|timeout|taking (ages|forever|too long|minutes)|response time|freezing on|freezes on|running hot|fan is spinning|hot and loud)/.test(q)) return 'kb:performance';
  return 'default';
}

  if (/\b(rsa|duo|authy|soft token|hard(ware)? token|security token|token fob|fob|securid|piv token|otp)\b/.test(q)) return 'kb:mfa';
  if (/\bsecurity code\b/.test(q)) return 'kb:mfa';
  return 'default';
}

  if (/\b(wfi|wirless|wifii|red inalambrica)\b/.test(q)) return 'wifi';
  if (/(team'?s|teamz|teem)\b/.test(q)) return 'kb:teams';
  if (/\b(prnter|priner|printr|pritner)\b/.test(q)) return 'printer';
  return 'default';
}

  if (/(can\s?t reach|can;t reach|cannot reach|can\s?t resolve|can;t resolve)/.test(q) && /(server|host|internal site|clinical pc|workstation)/.test(q)) return 'kb:networking';
  return 'default';
}
